using System.Text;
using UnityEditor;
using UnityEngine;

public class FishLineSim
{
    public static void Run()
    {
        StringBuilder sb = new StringBuilder();
        GameObject go = new GameObject("__line_sim");
        go.hideFlags = HideFlags.DontSave;
        LineRenderer line = go.AddComponent<LineRenderer>();

        line.positionCount = 2;
        line.useWorldSpace = true;
        line.SetPosition(0, new Vector3(0f, 1.18f, -1.15f));
        line.SetPosition(1, new Vector3(0f, -4f, -1.5f));

        // 先复现旧写法：只设 startWidth / endWidth，看会不会被曲线反算放大
        line.widthMultiplier = 1f;
        line.startWidth = 1f;
        line.endWidth = 1f;
        line.widthMultiplier = 0.02f;
        sb.AppendLine("legacy startWidth path -> size.x = " + line.bounds.size.x.ToString("0.0000"));

        // 新写法：显式平坦曲线 + 倍率，顺序无关
        line.startWidth = 1f;
        line.widthCurve = new AnimationCurve(new Keyframe(0f, 1f), new Keyframe(1f, 1f));
        line.widthMultiplier = 0.02f;
        sb.AppendLine("flat curve path     -> size.x = " + line.bounds.size.x.ToString("0.0000"));

        Object.DestroyImmediate(go);
        Debug.Log("[FishLineSim]\n" + sb);
    }
}
